using CustomCodeFramework.Postgres.EntityFramework.Configurations;using Dhole.Content.Domain.Media.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace Dhole.Content.Persistence.Configurations.Media;internal sealed class MediaReferenceConfiguration:EntityTypeConfigurationBase<MediaReference,Guid>{public override void Configure(EntityTypeBuilder<MediaReference>b){base.Configure(b);b.ToTable("media_references");b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.FileName).HasMaxLength(500).IsRequired();b.Property(x=>x.ContentType).HasMaxLength(160).IsRequired();b.Property(x=>x.AltText).HasMaxLength(600);b.Property(x=>x.Caption).HasMaxLength(1200);b.Property(x=>x.MetadataJson).HasColumnType("jsonb");b.HasIndex(x=>x.StorageFileId).IsUnique().HasFilter("is_deleted = false");}}
